const LOGICAL_TO_LTR = {
    start: "left",
    "start-top": "left-top",
    "start-bottom": "left-bottom",
    end: "right",
    "end-top": "right-top",
    "end-bottom": "right-bottom",
    "top-start": "top-left",
    "top-end": "top-right",
    "bottom-start": "bottom-left",
    "bottom-end": "bottom-right"
};
const LOGICAL_TO_RTL = {
    start: "right",
    "start-top": "right-top",
    "start-bottom": "right-bottom",
    end: "left",
    "end-top": "left-top",
    "end-bottom": "left-bottom",
    "top-start": "top-right",
    "top-end": "top-left",
    "bottom-start": "bottom-right",
    "bottom-end": "bottom-left"
};
export const normalizeLogicalAlignment = (alignment, direction) => {
    const map = direction === "rtl" ? LOGICAL_TO_RTL : LOGICAL_TO_LTR;
    const resolved = map[alignment];
    if (resolved !== undefined) {
        return resolved;
    }
    return alignment;
};
